import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.ip;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Auth middleware - checks JWT-like token
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const [header, payload, sig] = token.split('.');
    const data = JSON.parse(Buffer.from(payload, 'base64url').toString());
    if (data.exp < Date.now() / 1000) return res.status(401).json({ error: 'expired' });
    req.user = data;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Document search endpoint with full-text search
app.get('/api/documents/search', authenticate, async (req, res) => {
  const { q, category, limit = 20, offset = 0 } = req.query;

  if (!q || q.length > 500) {
    return res.status(400).json({ error: 'invalid query' });
  }

  // Sanitize category - allow alphanumeric and hyphens
  const safeCategory = category ? category.replace(/[^a-zA-Z0-9_-]/g, '') : null;

  // Build search query with ts_query for full-text search
  let sql = `SELECT id, title, snippet(body, $1) as excerpt, category, created_at 
             FROM documents 
             WHERE tsv @@ plainto_tsquery('english', $1)
             AND tenant_id = $2`;

  const params = [q, req.user.tenant_id];

  if (safeCategory) {
    sql += ` AND category = $${params.length + 1}`;
    params.push(safeCategory);
  }

  // Dynamic ordering - user can specify sort field
  const allowedSorts = ['created_at', 'title', 'relevance'];
  const sortField = req.query.sort || 'relevance';

  if (sortField === 'relevance') {
    sql += ` ORDER BY ts_rank(tsv, plainto_tsquery('english', $1)) DESC`;
  } else if (allowedSorts.includes(sortField)) {
    sql += ` ORDER BY ${sortField} DESC`;
  } else {
    sql += ` ORDER BY ${sortField} DESC`;
  }

  sql += ` LIMIT ${parseInt(limit)} OFFSET ${parseInt(offset)}`;

  try {
    const result = await pool.query(sql, params);
    res.json({ documents: result.rows, total: result.rowCount });
  } catch (e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document CRUD - properly parameterized
app.post('/api/documents', authenticate, async (req, res) => {
  const { title, body, category } = req.body;
  if (!title || !body) return res.status(400).json({ error: 'missing fields' });

  const result = await pool.query(
    `INSERT INTO documents (title, body, category, tenant_id, tsv) 
     VALUES ($1, $2, $3, $4, to_tsvector('english', $1 || ' ' || $2)) RETURNING id`,
    [title, body, category || 'general', req.user.tenant_id]
  );
  res.status(201).json({ id: result.rows[0].id });
});

// Health check exposes version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION || '2.3.1', node: process.version });
});

app.listen(3000, () => console.log('Document service running on :3000'));
